public class TableServicePlugin : ProgramPlugin, TableService, DomainObjectListener {

	private SwingUpdateManager updateMgr;
	private Map<Program, List<TableComponentProvider<object>>> programMap = new();

	private Map<Program, List<TableChooserDialog>> programToDialogMap = new();

	public TableServicePlugin(PluginTool tool) : base(tool)
    {

		updateMgr = new SwingUpdateManager(1000, () => updateProviders());

		createActions();
	}

	private void createActions() {
		//
		// Unusual Code: We, as a plugin, don't have any actions.  Our transient tables do have
		// 			     actions.  We need a way to have keybindings shared for all the different
		//				 actions.  Further, we need to register them now, not when the transient
		//               providers are created, as they would only appear in the options at
		//               that point.
		//
		DeleteTableRowAction.registerDummy(tool, getName());
	}

	/* @Override */
	protected void dispose() {
		programMap.clear();
		updateMgr.dispose();
		base.dispose();
	}

	/* @Override */
	protected void programClosed(Program program) {
		closeAllQueries(program);
	}

	/* @Override */
	protected void programDeactivated(Program program) {
		program.removeListener(this);
	}

	/* @Override */
	protected void programActivated(Program program) {
		program.addListener(this);
	}

	private void closeAllQueries(Program program) {
		clearTableComponentProviders(program);
		clearTableDialogs(program);
	}

	private void clearTableComponentProviders(Program program) {
		List<TableComponentProvider<object>> plist = programMap.get(program);
		if (plist == null) {
			return;
		}
		// make a copy of the list because the provider updates the list
		List<TableComponentProvider<object>> list = new(plist);
		foreach (TableComponentProvider<object> provider in list) {
			provider.closeComponent();
		}
		programMap.remove(program);
	}

	private void clearTableDialogs(Program program) {
		List<TableChooserDialog> dlist = programToDialogMap.get(program);
		if (dlist == null) {
			return;
		}
		// make a copy of the list because the dialog updates the list
		List<TableChooserDialog> list = new(dlist);
		foreach (TableChooserDialog dialog in list) {
			dialog.close();
		}
		programMap.remove(program);
	}

	/* @Override */
	public TableComponentProvider<T> showTable<T>(string title, string tableTypeName,
			GhidraProgramTableModel<T> model, string windowSubMenu, Navigatable navigatable) {

		GoToService gotoService = tool.getService(typeof(GoToService));
		Program program = model.getProgram();
		TableComponentProvider<T> cp = new(this, title, tableTypeName,
			model, program, gotoService, windowSubMenu, navigatable);
		addProvider(program, cp);
		return cp;
	}

	/* @Override */
	public TableComponentProvider<T> showTableWithMarkers<T>(string title, string tableTypeName,
			GhidraProgramTableModel<T> model, Color markerColor, Icon markerIcon,
			string windowSubMenu, Navigatable navigatable) {

		GoToService gotoService = tool.getService(typeof(GoToService));
		MarkerService markerService = tool.getService(typeof(MarkerService));
		Program program = model.getProgram();
		TableComponentProvider<T> cp = new(this, title, tableTypeName,
			model, program, gotoService, markerService, markerColor, markerIcon, windowSubMenu,
			navigatable);
		addProvider(program, cp);
		return cp;
	}

	private void addProvider(Program program, TableComponentProvider<object> provider) {
		List<TableComponentProvider<object>> list = programMap.get(program);
		if (list == null) {
			list = new();
			programMap.put(program, list);
		}
		list.add(provider);
	}

	void remove(TableComponentProvider<object> provider) {
		foreach (Program p in programMap.keySet()) {
			List<TableComponentProvider<object>> list = programMap.get(p);
			if (list.remove(provider)) {
				if (list.size() == 0) {
					programMap.remove(p);
					return;
				}
			}
		}
	}

	void removeDialog(TableServiceTableChooserDialog dialog) {
		foreach (Program p in programToDialogMap.keySet()) {
			List<TableChooserDialog> list = programToDialogMap.get(p);
			if (list.remove(dialog)) {
				if (list.size() == 0) {
					programToDialogMap.remove(p);
					return;
				}
			}
		}
	}

	/* @Override */
	public void domainObjectChanged(DomainObjectChangedEvent ev) {
		updateMgr.update();
	}

	public TableComponentProvider<object>[] getManagedComponents() {
		List<TableComponentProvider<object>> clist = getProviders();
		return clist.toArray(new TableComponentProvider[clist.size()]);
	}

	Program getProgram() {
		return currentProgram;
	}

	private List<TableComponentProvider<object>> getProviders() {
		List<TableComponentProvider<object>> clist = new();
		foreach (List<TableComponentProvider<object>> list in programMap.values()) {
			clist.addAll(list);
		}
		return clist;
	}

	private void updateProviders() {
		List<TableComponentProvider<object>> list = getProviders();
		foreach (TableComponentProvider<object> provider in list) {
			provider.refresh();
		}
	}

	/* @Override */
	public TableChooserDialog createTableChooserDialog(TableChooserExecutor executor,
			Program program, string title, Navigatable navigatable) {

		return createTableChooserDialog(executor, program, title, navigatable, false);
	}

	/* @Override */
	public TableChooserDialog createTableChooserDialog(TableChooserExecutor executor,
			Program program, string title, Navigatable navigatable, bool isModal) {

		GoToService gotoService = tool.getService(typeof(GoToService));

		if (gotoService != null && navigatable == null) {
			navigatable = gotoService.getDefaultNavigatable();
		}

		Navigatable nav = navigatable;
		TableChooserDialog dialog = Swing.runNow(
			() => new TableServiceTableChooserDialog(this, executor, program, title, nav, isModal));

		List<TableChooserDialog> list =
			programToDialogMap.computeIfAbsent(program, p => new());
		list.add(dialog);
		return dialog;
	}
}
